/* ---- ui-js/20-list-more.js ---- */
/* «Показать ещё»: loads ?page=N+1, appends its [data-list] items to the current list,
   marks loaded page numbers (.is-loaded), hides the button on the last page.
   Markup: list container [data-list], then the ListMore component [data-list-more]. */
(function () {
  document.querySelectorAll('[data-list-more]').forEach(function (box) {
    var btn = box.querySelector('[data-more]');
    var list = document.querySelector('[data-list]');
    if (!btn || !list) return;
    var total = Number(box.getAttribute('data-total'));
    var page = Number(box.getAttribute('data-current'));
    btn.addEventListener('click', function () {
      var next = page + 1;
      btn.setAttribute('aria-busy', 'true');
      var url = new URL(location.href);
      url.searchParams.set('page', next);
      fetch(url, { credentials: 'same-origin' })
        .then(function (r) { if (!r.ok) throw new Error(r.status); return r.text(); })
        .then(function (html) {
          var doc = new DOMParser().parseFromString(html, 'text/html');
          var src = doc.querySelector('[data-list]');
          if (src) Array.prototype.forEach.call(src.children, function (el) { list.appendChild(document.importNode(el, true)); });
          page = next;
          history.replaceState(null, '', url);
          box.querySelectorAll('.pager-num').forEach(function (n) {
            var p = Number(n.textContent);
            if (p <= page && !n.classList.contains('is-current')) n.classList.add('is-loaded');
          });
          if (page >= total) btn.hidden = true;
        })
        .catch(function () { location.href = url; })
        .then(function () { btn.removeAttribute('aria-busy'); });
    });
  });
})();

/* ---- ui-js/30-article.js ---- */
/* Article table of contents: highlights the section being read (.is-active).
   Markup: nav[data-toc] with links #id to headings in the text. */
(function () {
  var toc = document.querySelector('[data-toc]');
  if (!toc || !('IntersectionObserver' in window)) return;
  var links = toc.querySelectorAll('a[href^="#"]');
  var heads = [];
  links.forEach(function (a) {
    var h = document.getElementById(a.getAttribute('href').slice(1));
    if (h) heads.push(h);
  });
  if (!heads.length) return;
  function setActive(id) {
    links.forEach(function (a) { a.classList.toggle('is-active', a.getAttribute('href') === '#' + id); });
  }
  var io = new IntersectionObserver(function () {
    var cur = heads[0];
    heads.forEach(function (h) { if (h.getBoundingClientRect().top < 160) cur = h; });
    setActive(cur.id);
  }, { rootMargin: '-120px 0px -50% 0px' });
  heads.forEach(function (h) { io.observe(h); });
})();

/* ---- ui-js/30-contacts.js ---- */
/* Contacts: a city on the offices scheme ([data-rep-link] -> #rep-*) opens its accordion item
   (<details>) and scrolls to it. Also opens the item when the page is loaded with #rep-* in the URL. */
(function () {
  var links = document.querySelectorAll('[data-rep-link]');
  if (!links.length) return;
  function openRep(hash) {
    if (!/^#rep-[a-z]+$/.test(hash || '')) return null;
    var item = document.querySelector(hash);
    if (item && item.tagName === 'DETAILS') item.open = true;
    return item;
  }
  Array.prototype.forEach.call(links, function (a) {
    a.addEventListener('click', function (e) {
      var item = openRep(a.getAttribute('href'));
      if (!item) return;
      e.preventDefault();
      item.scrollIntoView({ behavior: 'smooth', block: 'center' });
      history.replaceState(null, '', a.getAttribute('href'));
    });
  });
  openRep(location.hash);
})();

/* ---- ui-js/30-news-article.js ---- */
/* Product carousel («Связанные приборы», news article): arrows scroll by one card,
   dots = scroll positions (rebuilt on resize), active dot follows the scroll.
   Markup: [data-rel] > [data-rel-track], [data-rel-prev], [data-rel-next], [data-rel-dots]. */
(function () {
  document.querySelectorAll('[data-rel]').forEach(function (box) {
    var track = box.querySelector('[data-rel-track]');
    var prev = box.querySelector('[data-rel-prev]');
    var next = box.querySelector('[data-rel-next]');
    var dotsBox = box.querySelector('[data-rel-dots]');
    var ctrl = prev && prev.parentNode;
    if (!track || !prev || !next || !dotsBox) return;

    function step() {
      var card = track.firstElementChild;
      if (!card) return 1;
      var gap = parseFloat(getComputedStyle(track).columnGap) || 0;
      return card.getBoundingClientRect().width + gap;
    }
    function count() {
      var max = track.scrollWidth - track.clientWidth;
      return max > 1 ? Math.ceil(max / step() - 0.05) + 1 : 1;
    }
    function current() {
      var max = track.scrollWidth - track.clientWidth;
      if (track.scrollLeft >= max - 2) return count() - 1;
      return Math.round(track.scrollLeft / step());
    }
    function go(i) {
      var max = track.scrollWidth - track.clientWidth;
      track.scrollTo({ left: Math.max(0, Math.min(max, i * step())) });
    }
    function update() {
      var n = count(), cur = current();
      ctrl.hidden = n < 2;
      Array.prototype.forEach.call(dotsBox.children, function (d, i) {
        d.classList.toggle('is-active', i === cur);
        if (i === cur) d.setAttribute('aria-current', 'true'); else d.removeAttribute('aria-current');
      });
      prev.disabled = cur <= 0;
      next.disabled = cur >= n - 1;
    }
    function build() {
      var n = count();
      if (dotsBox.children.length !== n) {
        dotsBox.innerHTML = '';
        for (var i = 0; i < n; i++) {
          var b = document.createElement('button');
          b.type = 'button';
          b.className = 'hc-dot';
          b.setAttribute('aria-label', 'Позиция ' + (i + 1));
          b.appendChild(document.createElement('i'));
          dotsBox.appendChild(b);
        }
      }
      update();
    }

    prev.addEventListener('click', function () { go(current() - 1); });
    next.addEventListener('click', function () { go(current() + 1); });
    dotsBox.addEventListener('click', function (e) {
      var d = e.target.closest('.hc-dot');
      if (d) go(Array.prototype.indexOf.call(dotsBox.children, d));
    });
    track.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', build);
    build();
  });
})();

/* ---- ui-js/30-product.js ---- */
/* Product card: gallery thumbs + tabs (role=tablist). Does nothing without the elements. */
(function () {
  'use strict';

  document.querySelectorAll('[data-gallery]').forEach(function (g) {
    var main = g.querySelector('[data-gallery-main]');
    var thumbs = g.querySelectorAll('.gallery-thumb');
    if (!main) return;
    thumbs.forEach(function (t) {
      t.addEventListener('click', function () {
        main.src = t.getAttribute('data-src');
        thumbs.forEach(function (x) {
          x.classList.toggle('is-active', x === t);
          x.setAttribute('aria-pressed', x === t ? 'true' : 'false');
        });
      });
    });
  });

  document.querySelectorAll('[data-tabs]').forEach(function (box) {
    var tabs = Array.prototype.slice.call(box.querySelectorAll('[role=tab]'));
    if (!tabs.length) return;
    function select(tab, focus) {
      tabs.forEach(function (t) {
        var on = t === tab;
        t.classList.toggle('is-active', on);
        t.setAttribute('aria-selected', on ? 'true' : 'false');
        t.tabIndex = on ? 0 : -1;
        var panel = document.getElementById(t.getAttribute('aria-controls'));
        if (panel) panel.hidden = !on;
      });
      if (focus) tab.focus();
    }
    tabs.forEach(function (t, i) {
      t.addEventListener('click', function () { select(t); });
      t.addEventListener('keydown', function (e) {
        var n = e.key === 'ArrowRight' ? i + 1 : e.key === 'ArrowLeft' ? i - 1 : e.key === 'Home' ? 0 : e.key === 'End' ? tabs.length - 1 : null;
        if (n === null) return;
        e.preventDefault();
        select(tabs[(n + tabs.length) % tabs.length], true);
      });
    });
  });
})();

/* ---- ui-js/30-reviews.js ---- */
/* Filter forms with [data-autosubmit] (reviews): a GET form without a button,
   submitted when a select changes; selected values are restored from the URL. */
(function () {
  var forms = document.querySelectorAll('form[data-autosubmit]');
  if (!forms.length) return;
  var params = new URLSearchParams(location.search);
  Array.prototype.forEach.call(forms, function (form) {
    Array.prototype.forEach.call(form.querySelectorAll('select'), function (sel) {
      var v = params.get(sel.name);
      if (v !== null) sel.value = v;
      sel.addEventListener('change', function () { form.submit(); });
    });
  });
})();

/* ---- ui-js/30-stock.js ---- */
/* Stock page: search by designation + category tabs, client-side over the rendered rows. */
(function () {
  'use strict';
  var box = document.querySelector('[data-stock]');
  if (!box) return;
  var search = box.querySelector('[data-stock-search]');
  var tabs = box.querySelectorAll('[data-stock-cat]');
  var rows = box.querySelectorAll('tbody tr');
  var empty = box.querySelector('[data-stock-empty]');
  var cat = 'all';

  function norm(s) { return (s || '').toLowerCase().replace(/\s+/g, ' ').trim(); }

  function apply() {
    var q = norm(search && search.value);
    var shown = 0;
    rows.forEach(function (r) {
      var ok = (cat === 'all' || r.getAttribute('data-cat') === cat) &&
        (!q || norm(r.getAttribute('data-product') + ' ' + r.getAttribute('data-name')).indexOf(q) !== -1);
      r.hidden = !ok;
      if (ok) shown++;
    });
    if (empty) empty.hidden = shown > 0;
  }

  tabs.forEach(function (t) {
    t.addEventListener('click', function () {
      cat = t.getAttribute('data-stock-cat');
      tabs.forEach(function (x) {
        x.classList.toggle('is-active', x === t);
        x.setAttribute('aria-pressed', x === t ? 'true' : 'false');
      });
      apply();
    });
  });
  if (search) search.addEventListener('input', apply);
})();
